create or replace function public.materialize_notification_event(p_notification_id uuid) returns integer language plpgsql security definer set search_path=public as $$ declare v_event public.notification_events%rowtype; v_count integer:=0; begin select * into v_event from public.notification_events where id=p_notification_id; if not found then return 0; end if; insert into public.notifications(user_id,type,title,body,data,created_at) select d.recipient_user_id,v_event.event_type,coalesce(v_event.payload->>'title','Kleenest update'),coalesce(v_event.payload->>'body','There is new information nearby.'),jsonb_build_object('notification_event_id',v_event.id,'location_id',v_event.location_id)||coalesce(v_event.payload,'{}'::jsonb),now() from public.notification_deliveries d where d.notification_id=v_event.id and d.channel='in_app' on conflict do nothing; get diagnostics v_count=row_count; return v_count; end; $$; create or replace function public.queue_push_deliveries_for_notification(p_notification_id uuid) returns integer language plpgsql security definer set search_path=public as $$ declare v_count integer:=0; begin insert into public.notification_push_deliveries(notification_id,subscription_id,status) select p_notification_id,s.id,'queued' from public.notification_deliveries d join public.notification_push_subscriptions s on s.user_id=d.recipient_user_id where d.notification_id=p_notification_id and d.channel='push' on conflict do nothing; get diagnostics v_count=row_count; return v_count; end; $$;
